 #ifndef INC_STM32F407_DRIVER_H_
#define INC_STM32F407_DRIVER_H_

#include 
#include 

/* ==========================================================================
 BASE ADDRESSES (All relevant peripherals)
 ========================================================================== */

#define BASE_ADDR 0x40000000U

/* SysTick (Private Peripheral Bus) */
#define SYSTICK_BASE 0xE000E010U

/* ==========================================================================
 AHB1 Peripherals (GPIOs, RCC, DMA, FLASH)
 ========================================================================== */
#define FLASH_ADDR (BASE_ADDR + 0x23C00U) /* 0x40023C00 (Flash interface) */
#define RCC_ADDR (BASE_ADDR + 0x23800U) /* 0x40023800 (RCC) */
#define GPIOE_ADDR (BASE_ADDR + 0x21000U) /* 0x40021000 */
#define GPIOD_ADDR (BASE_ADDR + 0x20C00U) /* 0x40020C00 */
#define GPIOC_ADDR (BASE_ADDR + 0x20800U) /* 0x40020800 */
#define GPIOB_ADDR (BASE_ADDR + 0x20400U) /* 0x40020400 */
#define GPIOA_ADDR (BASE_ADDR + 0x20000U) /* 0x40020000 */

/* ==========================================================================
 APB2 Peripherals
 ========================================================================== */
#define EXTI_ADDR (BASE_ADDR + 0x13C00U) /* 0x40013C00 (EXTI) */
#define SYSCFG_ADDR (BASE_ADDR + 0x13800U) /* 0x40013800 (SYSCFG) */
#define SDIO_ADDR (BASE_ADDR + 0x12C00U) /* 0x40012C00 (SDIO) */

/* ==========================================================================
 REGISTER STRUCTURES
 ========================================================================== */

/* FLASH Register Map */
typedef struct {
 volatile uint32_t ACR; /* 0x00: Flash access control register */
 volatile uint32_t KEYR; /* 0x04: Flash key register */
 volatile uint32_t OPTKEYR; /* 0x08: Flash option key register */
 volatile uint32_t SR; /* 0x0C: Flash status register */
 volatile uint32_t CR; /* 0x10: Flash control register */
 volatile uint32_t OPTCR; /* 0x14: Flash option control register */
} FLASH_Register;

/* RCC Register Map */
typedef struct {
 volatile uint32_t CR; /* 0x00: Clock control */
 volatile uint32_t PLLCFGR; /* 0x04: PLL configuration */
 volatile uint32_t CFGR; /* 0x08: Clock configuration */
 volatile uint32_t CIR; /* 0x0C: Clock interrupt */
 volatile uint32_t AHB1RSTR; /* 0x10: AHB1 reset */
 volatile uint32_t AHB2RSTR; /* 0x14: AHB2 reset */
 volatile uint32_t AHB3RSTR; /* 0x18: AHB3 reset */
 uint8_t RESERVED0[4]; /* 0x1C */
 volatile uint32_t APB1RSTR; /* 0x20: APB1 reset */
 volatile uint32_t APB2RSTR; /* 0x24: APB2 reset */
 uint8_t RESERVED1[8]; /* 0x28..0x2F */
 volatile uint32_t AHB1ENR; /* 0x30: AHB1 clock enable */
 volatile uint32_t AHB2ENR; /* 0x34: AHB2 clock enable */
 volatile uint32_t AHB3ENR; /* 0x38: AHB3 clock enable */
 uint8_t RESERVED2[4]; /* 0x3C */
 volatile uint32_t APB1ENR; /* 0x40: APB1 clock enable */
 volatile uint32_t APB2ENR; /* 0x44: APB2 clock enable */
 uint8_t RESERVED3[8]; /* 0x48..0x4F */
 volatile uint32_t AHB1LPENR; /* 0x50: AHB1 low‑power enable */
 volatile uint32_t AHB2LPENR; /* 0x54 */
 volatile uint32_t AHB3LPENR; /* 0x58 */
 uint8_t RESERVED4[4]; /* 0x5C */
 volatile uint32_t APB1LPENR; /* 0x60 */
 volatile uint32_t APB2LPENR; /* 0x64 */
 uint8_t RESERVED5[8]; /* 0x68..0x6F */
 volatile uint32_t BDCR; /* 0x70: Backup domain control */
 volatile uint32_t CSR; /* 0x74: Control/status */
 uint8_t RESERVED6[8]; /* 0x78..0x7F */
 volatile uint32_t SSCGR; /* 0x80: Spread spectrum */
 volatile uint32_t PLLI2SCFGR; /* 0x84 */
 volatile uint32_t PLLSAICFGR; /* 0x88 */
 volatile uint32_t DCKCFGR; /* 0x8C */
} RCC_Register;

/* GPIO Register Map */
typedef struct {
 volatile uint32_t MODER; /* 0x00: Mode */
 volatile uint32_t OTYPER; /* 0x04: Output type */
 volatile uint32_t OSPEEDR; /* 0x08: Speed */
 volatile uint32_t PUPDR; /* 0x0C: Pull-up/pull-down */
 volatile uint32_t IDR; /* 0x10: Input data */
 volatile uint32_t ODR; /* 0x14: Output data */
 volatile uint32_t BSRR; /* 0x18: Bit set/reset */
 volatile uint32_t LCKR; /* 0x1C: Lock */
 volatile uint32_t AFRL; /* 0x20: Alternate function low (pins 0‑7) */
 volatile uint32_t AFRH; /* 0x24: Alternate function high (pins 8‑15) */
} GPIO_Register;

/* SYSCFG Register Map */
typedef struct {
 volatile uint32_t MEMRMP; /* 0x00 */
 volatile uint32_t PMC; /* 0x04 */
 volatile uint32_t EXTICR1; /* 0x08: EXTI configuration 1 (pins 0‑3) */
 volatile uint32_t EXTICR2; /* 0x0C: pins 4‑7 */
 volatile uint32_t EXTICR3; /* 0x10: pins 8‑11 */
 volatile uint32_t EXTICR4; /* 0x14: pins 12‑15 */
 uint8_t RESERVED0[8]; /* 0x18..0x1F */
 volatile uint32_t CMPCR; /* 0x20 */
} SYSCFG_Register;

/* EXTI Register Map */
typedef struct {
 volatile uint32_t IMR; /* 0x00: Interrupt mask */
 volatile uint32_t EMR; /* 0x04: Event mask */
 volatile uint32_t RTSR; /* 0x08: Rising trigger */
 volatile uint32_t FTSR; /* 0x0C: Falling trigger */
 volatile uint32_t SWIER; /* 0x10: Software interrupt */
 volatile uint32_t PR; /* 0x14: Pending */
} EXTI_Register;

/* SDIO Register Map */
typedef struct {
 volatile uint32_t POWER; /* 0x00: Power control */
 volatile uint32_t CLKCR; /* 0x04: Clock control */
 volatile uint32_t ARG; /* 0x08: Argument */
 volatile uint32_t CMD; /* 0x0C: Command */
 volatile uint32_t RESPCMD; /* 0x10: Response command */
 volatile uint32_t RESP1; /* 0x14: Response 1 */
 volatile uint32_t RESP2; /* 0x18: Response 2 */
 volatile uint32_t RESP3; /* 0x1C: Response 3 */
 volatile uint32_t RESP4; /* 0x20: Response 4 */
 volatile uint32_t DTIMER; /* 0x24: Data timer */
 volatile uint32_t DLEN; /* 0x28: Data length */
 volatile uint32_t DCTRL; /* 0x2C: Data control */
 volatile uint32_t DCOUNT; /* 0x30: Data counter */
 volatile uint32_t STA; /* 0x34: Status */
 volatile uint32_t ICR; /* 0x38: Interrupt clear */
 volatile uint32_t MASK; /* 0x3C: Mask */
 volatile uint32_t FIFOCNT; /* 0x48: FIFO counter */
 volatile uint32_t FIFO; /* 0x80: Data FIFO */
} SDIO_Register;

/* SysTick Register Map */
typedef struct {
 volatile uint32_t CSR; /* 0x00: Control/status */
 volatile uint32_t RVR; /* 0x04: Reload value */
 volatile uint32_t CVR; /* 0x08: Current value */
 volatile uint32_t CALIB; /* 0x0C: Calibration */
} SYSTICK_Register;

/* ==========================================================================
 POINTERS TO PERIPHERALS
 ========================================================================== */

#define FLASH ((FLASH_Register*)FLASH_ADDR)
#define RCC ((RCC_Register*)RCC_ADDR)
#define GPIOA ((GPIO_Register*)GPIOA_ADDR)
#define GPIOB ((GPIO_Register*)GPIOB_ADDR)
#define GPIOC ((GPIO_Register*)GPIOC_ADDR)
#define GPIOD ((GPIO_Register*)GPIOD_ADDR)
#define GPIOE ((GPIO_Register*)GPIOE_ADDR)

#define SYSCFG ((SYSCFG_Register*)SYSCFG_ADDR)
#define EXTI ((EXTI_Register*)EXTI_ADDR)
#define SDIO ((SDIO_Register*)SDIO_ADDR)
#define SYSTICK ((SYSTICK_Register*)SYSTICK_BASE)

/* ==========================================================================
 CLOCK ENABLE / DISABLE MACROS (GPIO, DMA, SDIO, SYSCFG)
 ========================================================================== */

/* --- AHB1 (GPIOs, DMA2) --- */
#define GPIOA_PCLK_ENABLE (RCC->AHB1ENR |= (1 AHB1ENR |= (1 AHB1ENR |= (1 AHB1ENR |= (1 AHB1ENR |= (1 AHB1ENR |= (1 APB2ENR |= (1 APB2ENR |= (1 CFGR >> 2) & 0x03;
 if (clksrc == HSI) {
 sysclk = HSI_VALUE;
 } else if (clksrc == HSE) {
 sysclk = HSE_VALUE;
 } else if (clksrc == PLL) {
 uint32_t pllsrc, pllm, plln, pllp;
 pllsrc = (RCC->PLLCFGR >> 22) & 0x01;
